-- CURIÓ · catálogo inicial de 50 conquistas do aluno
on conflict(slug) do update set name=excluded.name,description=excluded.description,icon=excluded.icon,color_key=excluded.color_key,active=excluded.active,unlock_hint=excluded.unlock_hint,sort_order=excluded.sort_order;

update public.achievements set active=false where slug='olho-de-tamandua' and exists(select 1 from public.achievements where slug='olhos-do-tamandua');

select a.id,x.rule_type,x.threshold from (values
('calma-da-capivara','improvements',1),('voz-da-arara','open_answers',1),('imaginacao-do-boto','open_answers',3),('pratica-do-mico','notebooks_submitted',1),('olhos-do-tamandua','distinct_subjects',2),('coragem-da-onca','improvements',3),('voo-da-harpia','reviewed_missions',10),
('primeira-descoberta','reviewed_missions',1),('trilha-de-tres','reviewed_missions',3),('cinco-passos','reviewed_missions',5),('dez-descobertas','reviewed_missions',10),('vinte-descobertas','reviewed_missions',20),('cinquenta-descobertas','reviewed_missions',50),('cem-descobertas','reviewed_missions',100),
('primeira-pagina','notebooks_submitted',1),('caderno-3','notebooks_submitted',3),('caderno-5','notebooks_submitted',5),('caderno-10','notebooks_submitted',10),('caderno-20','notebooks_submitted',20),
('sequencia-2','streak_days',2),('sequencia-3','streak_days',3),('sequencia-5','streak_days',5),('sequencia-7','streak_days',7),('sequencia-14','streak_days',14),('sequencia-30','streak_days',30),
('estrelas-10','stars',10),('estrelas-25','stars',25),('estrelas-50','stars',50),('estrelas-100','stars',100),('estrelas-250','stars',250),('estrelas-500','stars',500),
('melhora-1','improvements',1),('melhora-3','improvements',3),('melhora-5','improvements',5),('melhora-10','improvements',10),
('perfeito-1','perfect_missions',1),('perfeito-3','perfect_missions',3),('perfeito-5','perfect_missions',5),('perfeito-10','perfect_missions',10),
('materias-2','distinct_subjects',2),('materias-3','distinct_subjects',3),('materias-4','distinct_subjects',4),('materias-5','distinct_subjects',5),
('curso-1','courses_completed',1),('curso-3','courses_completed',3),('curso-5','courses_completed',5),('dias-ativos-5','active_days',5),('dias-ativos-20','active_days',20),('respostas-abertas-3','open_answers',3),('respostas-abertas-10','open_answers',10)
) x(slug,rule_type,threshold) join public.achievements a on a.slug=x.slug
on conflict(achievement_id) do update set rule_type=excluded.rule_type,threshold=excluded.threshold,updated_at=now();

select text,true from (values
('Leia a pergunta até o fim antes de escolher uma resposta.'),('Explique com suas palavras: quando você consegue explicar, aprende duas vezes.'),('Errou? Marque a parte que confundiu você e tente de novo por outro caminho.'),('Estudar dez minutos com atenção vale mais do que muito tempo distraído.'),('Antes de começar, descubra qual é exatamente a tarefa.'),('Faça uma pausa curta quando perceber que está respondendo no automático.'),('No caderno, capriche no caminho da resposta, não só no resultado.'),('Compare o que você pensava antes com o que entendeu depois.'),('Se uma palavra parece difícil, procure uma pista na frase ao redor.'),('Uma boa pergunta também é uma forma de aprender.'),('Tente encontrar um exemplo da matéria na sua vida cotidiana.'),('Quando terminar, revise uma resposta que você achou fácil demais.'),('Organize os dados da questão antes de fazer a conta.'),('Em textos, procure quem fez o quê, onde e por quê.'),('Transforme o conteúdo em uma história curta para lembrar melhor.'),('Use desenhos, setas ou esquemas quando uma ideia estiver confusa.'),('Pratique primeiro sem olhar a resposta. Depois confira.'),('Diga em voz alta o que você acabou de aprender.'),('Separe o conteúdo grande em pequenas partes.'),('Antes da prova, revise seus erros antigos: eles mostram onde treinar.'),('Se travar, comece pelo que você já sabe sobre o assunto.'),('Procure relações entre matérias diferentes. O conhecimento se conecta.'),('Faça uma pergunta que a professora poderia colocar sobre este conteúdo.'),('Releia a instrução antes de enviar uma atividade.'),('Aprender também é perceber quando você precisa de ajuda.'),('Use uma palavra nova em uma frase sua para ela fazer sentido.'),('Em Ciências, tente prever o resultado antes de ler a explicação.'),('Em História, pergunte o que mudou e o que continuou igual.'),('Em Geografia, tente localizar o assunto em um mapa mental ou real.'),('Em Matemática, confira se sua resposta combina com o tamanho esperado.'),('Pequenos avanços repetidos viram uma grande mudança.')) v(text)
where not exists(select 1 from public.daily_tips d where d.text=v.text);
